<!doctype html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f172a"><link rel="manifest" href="/trainingapp/public/manifest.json"><script src="https://cdn.tailwindcss.com"></script><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><link rel="stylesheet" href="/trainingapp/public/css/app.css"><title>FitTrack — Progres</title></head>
<body class="bg-slate-50 text-slate-900"><main class="mx-auto max-w-3xl px-4 pb-28 pt-6 space-y-6">
<header><a class="text-sm font-bold text-slate-500" href="/trainingapp/">← FitTrack</a><h1 class="mt-2 text-3xl font-black">Progres</h1><p class="mt-1 text-slate-500">Wybierz dzień w kalendarzu, aby dodać lub edytować pomiar.</p></header>
<section class="grid grid-cols-2 gap-3"><div class="rounded-2xl bg-white p-4 ring-1 ring-slate-200"><p class="text-sm text-slate-500">Ostatnia masa</p><p id="latestWeight" class="mt-1 text-2xl font-black">—</p><p id="lastWeighDate" class="mt-1 text-xs text-slate-400">Brak pomiaru</p></div><div class="rounded-2xl bg-white p-4 ring-1 ring-slate-200"><p class="text-sm text-slate-500">Zmiana od pierwszego pomiaru</p><p id="weightChange" class="mt-1 text-2xl font-black">—</p></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4"><div><h2 class="text-xl font-bold">Kalendarz pomiarów</h2><p class="text-sm text-slate-500">Wybierz datę. Dni z zapisanym pomiarem są oznaczone kropką.</p></div><div class="flex items-center justify-between gap-3"><button id="prevMonth" type="button" class="rounded-xl border px-4 py-2 font-bold" aria-label="Poprzedni miesiąc">←</button><h3 id="monthLabel" class="text-lg font-black capitalize"></h3><button id="nextMonth" type="button" class="rounded-xl border px-4 py-2 font-bold" aria-label="Następny miesiąc">→</button></div><div class="grid grid-cols-7 gap-1 text-center text-xs font-bold text-slate-500"><div>Pn</div><div>Wt</div><div>Śr</div><div>Cz</div><div>Pt</div><div>So</div><div>Nd</div></div><div id="calendarGrid" class="grid grid-cols-7 gap-1.5"></div><div class="flex flex-wrap gap-3 text-xs text-slate-500"><span>● Zapisany pomiar</span><span class="text-emerald-700">■ Wybrany dzień</span></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4"><div><h2 class="text-xl font-bold">Pomiar ciała</h2><p class="text-sm text-slate-500">Jeden wpis na datę. Zapisany wpis można edytować. Obwody można uzupełniać dla piątków.</p></div><div id="weeklyStatus" class="rounded-xl bg-slate-50 p-3 text-sm text-slate-600">Wybierz dzień…</div><form id="form" class="grid grid-cols-2 gap-3"><label class="col-span-2 text-sm font-semibold">Wybrana data<input id="measurementDate" name="measurement_date" type="date" readonly required class="mt-1 w-full rounded-xl border bg-slate-100 p-3"></label><label class="col-span-2 text-sm font-semibold">Masa ciała (kg)<input name="weight_kg" type="number" min="20" max="400" step="0.1" required class="mt-1 w-full rounded-xl border p-3" placeholder="np. 96,4"></label><div id="circumferenceNotice" class="col-span-2 rounded-xl bg-blue-50 p-3 text-sm text-blue-800">Obwody są dostępne po wybraniu piątku.</div><div id="circumferenceFields" class="col-span-2 grid grid-cols-2 gap-3"><label class="text-sm font-semibold">Talia (cm)<input name="waist_cm" type="number" min="1" max="300" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Klatka (cm)<input name="chest_cm" type="number" min="1" max="300" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Ramię (cm)<input name="arm_cm" type="number" min="1" max="150" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Udo (cm)<input name="thigh_cm" type="number" min="1" max="200" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label></div><button id="saveButton" class="col-span-2 rounded-xl bg-slate-900 p-3 font-bold text-white">Zapisz pomiar</button><button id="cancelEdit" type="button" class="col-span-2 hidden rounded-xl border p-3 font-bold">Wróć do dzisiejszego pomiaru</button><p id="notice" class="col-span-2 text-sm"></p></form></section>
<section class="rounded-2xl bg-white p-4 ring-1 ring-slate-200"><p class="text-sm text-slate-500">Pomiarów zapisanych</p><p id="measurementCount" class="mt-1 text-xl font-black">0</p></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><div><h2 class="text-xl font-bold">Historia pomiarów</h2><p id="historyCount" class="text-sm text-slate-500"></p></div><div id="history" class="space-y-3">Ładowanie…</div><button id="moreHistory" type="button" class="hidden w-full rounded-xl border p-3 font-bold">Pokaż kolejne 5</button></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><div><h2 class="text-xl font-bold">Masa ciała w czasie</h2><p class="text-sm text-slate-500">Trend masy ciała.</p></div><div class="relative h-64"><canvas id="weightChart"></canvas></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4"><div><h2 class="text-xl font-bold">Tygodniowy bilans kaloryczny</h2><p class="text-sm text-slate-500">Szacowany deficyt liczony z zapotrzebowania na utrzymanie wagi i zapisanych kalorii. Dni bez wpisu nie są zgadywane.</p></div><div class="grid grid-cols-2 gap-3"><div class="rounded-2xl bg-slate-50 p-3"><p class="text-xs text-slate-500">Bilans od poniedziałku</p><p id="weeklyDeficitValue" class="mt-1 text-2xl font-black">—</p><p id="weeklyLoggedDays" class="mt-1 text-xs text-slate-500">—</p></div><div class="rounded-2xl bg-slate-50 p-3"><p class="text-xs text-slate-500">Cel deficytu / tydzień</p><p id="weeklyDeficitGoal" class="mt-1 text-2xl font-black">—</p><p id="weeklyDeficitPct" class="mt-1 text-xs text-slate-500">—</p></div></div><div class="flex justify-between gap-2 text-sm"><span class="text-slate-500">Realizacja celu</span><strong id="weeklyDeficitLabel">—</strong></div><div class="relative h-3 rounded-full bg-slate-100"><div id="weeklyDeficitBar" class="absolute inset-y-0 left-0 rounded-full bg-emerald-500 transition-all" style="width:0%;max-width:none"></div></div><p id="weeklyDeficitNote" class="text-xs text-slate-500">Pasek może przekroczyć 100%, aby pokazać wynik ponad cel.</p><div><h3 class="font-bold">Deficyt / nadwyżka dzień po dniu</h3><p class="text-xs text-slate-500">Wartości dodatnie oznaczają deficyt, ujemne — nadwyżkę.</p><div class="relative mt-2 h-64"><canvas id="weeklyDeficitChart"></canvas></div></div><div><h3 class="font-bold">Bilans narastająco</h3><div class="relative mt-2 h-64"><canvas id="weeklyCumulativeChart"></canvas></div></div></section><section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><div><h2 class="text-xl font-bold">Kalorie i makroskładniki</h2><p class="text-sm text-slate-500">Dzienne wpisy z ostatnich 30 dni.</p></div><div class="relative h-64"><canvas id="calorieChart"></canvas></div><div class="relative h-64"><canvas id="macroChart"></canvas></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><h2 class="text-xl font-bold">Historia treningów</h2><div id="sessions" class="space-y-3">Ładowanie…</div></section>
</main><nav class="fixed inset-x-0 bottom-0 z-40 border-t bg-white/95 backdrop-blur"><div class="mx-auto grid max-w-3xl grid-cols-5 text-center text-xs font-bold"><a class="p-3" href="/trainingapp/">⌂<br>Home</a><a class="p-3 text-slate-500" href="/trainingapp/calendar.php">▦<br>Kalendarz</a><a class="p-3 text-slate-500" href="/trainingapp/workouts.php">◈<br>Treningi</a><a class="p-3" href="/trainingapp/progress.php">↗<br>Progres</a><a class="p-3 text-slate-500" href="/trainingapp/nutrition.php">◉<br>Dieta</a></div></nav>
<script>
const API='/trainingapp/api';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){const r=await fetch(API+'/'+p,{headers:{'Content-Type':'application/json'},...o});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Błąd API');return d}const pad=n=>String(n).padStart(2,'0');function localDate(d=new Date()){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}const today=localDate();let measurements=[],weightChart=null,calorieChart=null,macroChart=null,weeklyDeficitChart=null,weeklyCumulativeChart=null,selectedDate=today,calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),historyLimit=5;
function isFriday(date){return new Date(date+'T12:00:00').getDay()===5}
function dateRecord(date){return measurements.find(x=>x.measurement_date===date)||null}
function setFormRecord(date,record=dateRecord(date)){selectedDate=date;document.querySelector('#measurementDate').value=date;document.querySelector('[name=weight_kg]').value=record?.weight_kg??'';for(const k of ['waist_cm','chest_cm','arm_cm','thigh_cm'])document.querySelector('[name='+k+']').value=record?.[k]??'';const friday=isFriday(date);document.querySelector('#circumferenceFields').classList.toggle('hidden',!friday);document.querySelector('#circumferenceNotice').classList.toggle('hidden',friday);document.querySelectorAll('#circumferenceFields input').forEach(el=>{el.disabled=!friday});document.querySelector('#saveButton').textContent=record?'Zapisz zmiany':'Zapisz pomiar';document.querySelector('#cancelEdit').classList.toggle('hidden',date===today);document.querySelector('#weeklyStatus').textContent=record?'Wpis z '+date+' jest zapisany. Możesz edytować jego wartości.':(date>today?'Nie można dodawać pomiarów z przyszłości.':'Brak wpisu dla '+date+'. Uzupełnij masę ciała.'+(friday?' Możesz też podać obwody.':''));document.querySelector('#weeklyStatus').className='rounded-xl p-3 text-sm '+(record?'bg-emerald-50 text-emerald-800':date>today?'bg-amber-50 text-amber-800':'bg-slate-50 text-slate-600');document.querySelector('#saveButton').disabled=date>today;document.querySelector('#saveButton').classList.toggle('opacity-50',date>today);document.querySelector('#cancelEdit').textContent='Wróć do dzisiejszego pomiaru';document.querySelector('#notice').textContent='';renderCalendar()}
function renderCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();document.querySelector('#monthLabel').textContent=calendarMonth.toLocaleDateString('pl-PL',{month:'long',year:'numeric'});const first=new Date(y,m,1),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),grid=document.querySelector('#calendarGrid');let html='';for(let i=0;i<offset;i++)html+='<div class="min-h-12"></div>';for(let day=1;day<=days;day++){const date=y+'-'+pad(m+1)+'-'+pad(day),rec=dateRecord(date),future=date>today,selected=date===selectedDate;html+='<button type="button" data-date="'+date+'" '+(future?'disabled':'')+' class="relative flex min-h-12 flex-col items-center justify-center rounded-xl border text-sm font-bold transition '+(selected?'border-emerald-700 bg-emerald-700 text-white shadow':'border-slate-100 bg-white hover:border-slate-300')+(future?' opacity-30':'')+'"><span>'+day+'</span>'+(rec?'<span class="mt-0.5 text-[9px] '+(selected?'text-white':'text-emerald-600')+'">●</span>':'<span class="mt-0.5 h-2"></span>')+'</button>'}grid.innerHTML=html;grid.querySelectorAll('button[data-date]').forEach(b=>b.addEventListener('click',()=>{const d=b.dataset.date;setFormRecord(d);document.querySelector('#form').scrollIntoView({behavior:'smooth',block:'start'})}));document.querySelector('#prevMonth').disabled=y===2000&&m===0;document.querySelector('#nextMonth').disabled=(y===new Date().getFullYear()&&m===new Date().getMonth());document.querySelector('#nextMonth').classList.toggle('opacity-40',document.querySelector('#nextMonth').disabled)}
function chartOptions(yTitle){return {responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom'}},scales:{x:{ticks:{maxTicksLimit:8}},y:{beginAtZero:false,title:{display:true,text:yTitle}}}}}
function renderHistory(){const list=measurements.slice().sort((a,b)=>b.measurement_date.localeCompare(a.measurement_date)),visible=list.slice(0,historyLimit);document.querySelector('#historyCount').textContent=list.length+' wpisów łącznie';document.querySelector('#history').innerHTML=visible.map(x=>'<article class="rounded-2xl border p-4"><div class="flex items-start justify-between gap-3"><div><h3 class="font-bold">'+esc(x.measurement_date)+'</h3><p class="mt-1 text-lg font-black">'+(x.weight_kg!==null?esc(x.weight_kg)+' kg':'Brak masy')+'</p><p class="text-sm text-slate-500">Talia '+(x.waist_cm??'—')+' cm · Klatka '+(x.chest_cm??'—')+' cm · Ramię '+(x.arm_cm??'—')+' cm · Udo '+(x.thigh_cm??'—')+' cm</p></div><button class="edit shrink-0 rounded-lg border px-3 py-2 text-sm font-bold" data-date="'+esc(x.measurement_date)+'">Edytuj</button></div></article>').join('')||'<p class="text-slate-500">Brak zapisanych pomiarów.</p>';document.querySelector('#moreHistory').classList.toggle('hidden',visible.length>=list.length);document.querySelector('#moreHistory').textContent='Pokaż kolejne 5 ('+Math.min(5,list.length-visible.length)+')';document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{const d=b.dataset.date;calendarMonth=new Date(Number(d.slice(0,4)),Number(d.slice(5,7))-1,1);setFormRecord(d);document.querySelector('#form').scrollIntoView({behavior:'smooth',block:'start'})})}
async function load(){const [allMeasurements,sessions,nutrition,settings]=await Promise.all([api('measurements'),api('workout-sessions?limit=30'),api('nutrition?from='+localDate(new Date(Date.now()-29*86400000))+'&to='+today),api('settings')]);measurements=allMeasurements;const weights=measurements.filter(x=>x.weight_kg!==null&&x.weight_kg!=='').slice().sort((a,b)=>a.measurement_date.localeCompare(b.measurement_date));document.querySelector('#latestWeight').textContent=weights.length?Number(weights[weights.length-1].weight_kg).toFixed(1)+' kg':'—';document.querySelector('#lastWeighDate').textContent=weights.length?'Ostatni wpis: '+weights[weights.length-1].measurement_date:'Brak wpisów';document.querySelector('#measurementCount').textContent=measurements.length;if(weights.length>1){const delta=Number(weights[weights.length-1].weight_kg)-Number(weights[0].weight_kg);document.querySelector('#weightChange').textContent=(delta>0?'+':'')+delta.toFixed(1)+' kg';document.querySelector('#weightChange').className='mt-1 text-2xl font-black '+(delta<0?'text-emerald-700':delta>0?'text-rose-600':'')}else document.querySelector('#weightChange').textContent='—';
if(weightChart)weightChart.destroy();weightChart=new Chart(document.getElementById('weightChart'),{type:'line',data:{labels:weights.map(x=>x.measurement_date),datasets:[{label:'Masa (kg)',data:weights.map(x=>Number(x.weight_kg)),tension:.25,spanGaps:true}]},options:chartOptions('kg')});
const food=nutrition.slice().sort((a,b)=>a.entry_date.localeCompare(b.entry_date));const weekNow=new Date(today+'T12:00:00');weekNow.setDate(weekNow.getDate()-((weekNow.getDay()+6)%7));const weekStart=weekNow.getFullYear()+'-'+pad(weekNow.getMonth()+1)+'-'+pad(weekNow.getDate()),maintenance=Number(settings.maintenance_calories)||3100,dailyGoal=Number(settings.daily_calories)||2450,weeklyGoal=Math.max(0,(maintenance-dailyGoal)*7),weekFood=food.filter(x=>x.entry_date>=weekStart&&x.entry_date<=today),foodByDate=new Map(weekFood.map(x=>[x.entry_date,x])),weekLabels=[],dailyDeficits=[],cumulative=[];let running=0,logged=0;for(let d=new Date(weekStart+'T12:00:00');d<=new Date(today+'T12:00:00');d.setDate(d.getDate()+1)){const key=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()),entry=foodByDate.get(key);weekLabels.push(d.toLocaleDateString('pl-PL',{weekday:'short',day:'2-digit'}));if(entry){const deficit=maintenance-(Number(entry.calories)||0);dailyDeficits.push(deficit);running+=deficit;logged++}else dailyDeficits.push(null);cumulative.push(logged?running:null)}const pct=weeklyGoal>0?running/weeklyGoal*100:0;document.querySelector('#weeklyDeficitValue').textContent=Math.round(running).toLocaleString('pl-PL')+' kcal';document.querySelector('#weeklyDeficitValue').className='mt-1 text-2xl font-black '+(running>=0?'text-emerald-700':'text-rose-600');document.querySelector('#weeklyLoggedDays').textContent='Wpisy: '+logged+' / '+weekLabels.length+' dni';document.querySelector('#weeklyDeficitGoal').textContent=Math.round(weeklyGoal).toLocaleString('pl-PL')+' kcal';document.querySelector('#weeklyDeficitPct').textContent=weeklyGoal>0?Math.round(pct)+'% celu':'Ustaw cel kaloryczny niższy od utrzymania';document.querySelector('#weeklyDeficitLabel').textContent=weeklyGoal>0?Math.round(pct)+'%':'—';const bar=document.querySelector('#weeklyDeficitBar');bar.style.width=Math.max(0,pct)+'%';bar.className='absolute inset-y-0 left-0 rounded-full transition-all '+(running<0?'bg-rose-500':'bg-emerald-500');document.querySelector('#weeklyDeficitNote').textContent=pct>100?'Cel przekroczony o '+Math.round(running-weeklyGoal).toLocaleString('pl-PL')+' kcal. Pasek celowo wychodzi poza 100%, aby pokazać nadwyżkę realizacji.':logged<weekLabels.length?'Obliczenia obejmują tylko dni z zapisanym jedzeniem; brak wpisu nie oznacza zera kalorii.':'Deficyt jest szacunkiem — porównuj go z trendem masy ciała.';if(weeklyDeficitChart)weeklyDeficitChart.destroy();weeklyDeficitChart=new Chart(document.getElementById('weeklyDeficitChart'),{type:'bar',data:{labels:weekLabels,datasets:[{label:'Deficyt / nadwyżka (kcal)',data:dailyDeficits}]},options:{...chartOptions('kcal'),scales:{...chartOptions('kcal').scales,y:{beginAtZero:true,title:{display:true,text:'kcal'}}}}});if(weeklyCumulativeChart)weeklyCumulativeChart.destroy();weeklyCumulativeChart=new Chart(document.getElementById('weeklyCumulativeChart'),{type:'line',data:{labels:weekLabels,datasets:[{label:'Bilans narastająco (kcal)',data:cumulative,tension:.25,spanGaps:false},{label:'Cel tygodniowy',data:weekLabels.map((_,i)=>weeklyGoal*(i+1)/7),borderDash:[5,5],pointRadius:0}]},options:chartOptions('kcal')});if(calorieChart)calorieChart.destroy();calorieChart=new Chart(document.getElementById('calorieChart'),{type:'line',data:{labels:food.map(x=>x.entry_date),datasets:[{label:'Spożyte kcal',data:food.map(x=>Number(x.calories)||0),tension:.25},{label:'Spalone kcal',data:food.map(x=>x.burned_calories===null?null:Number(x.burned_calories)),tension:.25}]},options:chartOptions('kcal')});if(macroChart)macroChart.destroy();macroChart=new Chart(document.getElementById('macroChart'),{type:'line',data:{labels:food.map(x=>x.entry_date),datasets:[{label:'Białko (g)',data:food.map(x=>Number(x.protein_g)||0),tension:.25},{label:'Węglowodany (g)',data:food.map(x=>Number(x.carbs_g)||0),tension:.25},{label:'Tłuszcze (g)',data:food.map(x=>Number(x.fats_g)||0),tension:.25}]},options:chartOptions('g')});
renderCalendar();renderHistory();setFormRecord(selectedDate,dateRecord(selectedDate));
document.querySelector('#sessions').innerHTML=sessions.map(x=>'<article class="rounded-2xl border p-4"><h3 class="font-bold">'+esc(x.workout_name_snapshot)+'</h3><p class="text-sm text-slate-500">'+esc(x.started_at)+' · '+(x.ended_at?'Zakończony':'W trakcie')+'</p><p class="mt-1 text-sm">'+(x.exercise_count||0)+' ćwiczeń · '+(x.set_count||0)+' serii'+(x.duration_seconds?' · '+Math.round(x.duration_seconds/60)+' min':'')+'</p><a class="mt-2 inline-flex rounded-lg border px-3 py-2 text-sm" href="/trainingapp/workout.php?session_id='+x.id+'">'+(x.ended_at?'Podgląd':'Wróć do treningu')+'</a></article>').join('')||'<p class="text-slate-500">Historia treningów pojawi się tutaj po pierwszej sesji.</p>'}
function showError(e){const n=document.querySelector('#notice');n.textContent=e.message;n.className='col-span-2 text-sm text-red-600'}
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();const date=selectedDate;if(date>today){showError(new Error('Nie można zapisywać pomiarów z przyszłości.'));return}const body=Object.fromEntries(new FormData(e.target).entries());body.measurement_date=date;for(const k of ['weight_kg','waist_cm','chest_cm','arm_cm','thigh_cm'])body[k]=body[k]===''||body[k]===undefined?null:Number(body[k]);const existing=dateRecord(date);if(!isFriday(date)){for(const k of ['waist_cm','chest_cm','arm_cm','thigh_cm'])body[k]=existing?.[k]??null}try{await api('measurements',{method:'POST',body:JSON.stringify(body)});await load();setFormRecord(date,dateRecord(date));document.querySelector('#notice').textContent='Pomiar zapisany. Możesz edytować ten wpis, wybierając tę datę w kalendarzu.';document.querySelector('#notice').className='col-span-2 text-sm text-emerald-700'}catch(err){showError(err)}};
document.querySelector('#cancelEdit').onclick=()=>{calendarMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);setFormRecord(today,dateRecord(today));window.scrollTo({top:0,behavior:'smooth'})};document.querySelector('#prevMonth').onclick=()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);renderCalendar()};document.querySelector('#nextMonth').onclick=()=>{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);renderCalendar()};document.querySelector('#moreHistory').onclick=()=>{historyLimit+=5;renderHistory()};load().catch(showError);
</script></body></html>